--
-- Create or alter procedure [wf].[wf_worker_authenticate]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_worker_authenticate]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_worker_authenticate
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000)
AS
BEGIN
    SET NOCOUNT ON;

    IF @worker_id IS NULL
        THROW 50002, N''worker_id is required.'', 1;

    DECLARE @tok NVARCHAR(4000) = NULLIF(LTRIM(RTRIM(@worker_token)), N'''');
    IF @tok IS NULL
        THROW 50002, N''worker_token is required.'', 1;

    DECLARE @hash VARBINARY(32) = HASHBYTES(N''SHA2_256'', @tok);

    IF NOT EXISTS (
        SELECT 1
        FROM wf.worker_token AS wt
        INNER JOIN wf.worker AS w ON w.id = wt.worker_id
        INNER JOIN wf.cluster AS c ON c.id = w.cluster_id
        WHERE wt.worker_id = @worker_id
          AND wt.token_hash = @hash
          AND wt.status = N''ACTIVE''
          AND (wt.expires_at_utc IS NULL OR wt.expires_at_utc > SYSUTCDATETIME())
          AND w.status = N''REGISTERED''
          AND c.status = N''ACTIVE''
    )
        THROW 50003, N''Invalid or unauthorized worker credentials.'', 1;

    UPDATE wf.worker
    SET last_seen_at_utc = SYSUTCDATETIME()
    WHERE id = @worker_id;
END;
'
GO

--
-- Create or alter procedure [wf].[sp_worker_request_task]
--
GO
PRINT (N'Create or alter functions for worker capability dispatch')
GO
/* CREATE OR ALTER cannot change NVARCHAR → json; drop dependents first. */
IF OBJECT_ID(N'wf.sp_worker_request_task', N'P') IS NOT NULL
    DROP PROCEDURE wf.sp_worker_request_task;
IF OBJECT_ID(N'wf.wf_worker_capability_allowed', N'FN') IS NOT NULL
    DROP FUNCTION wf.wf_worker_capability_allowed;
IF OBJECT_ID(N'wf.wf_worker_is_omnibus', N'FN') IS NOT NULL
    DROP FUNCTION wf.wf_worker_is_omnibus;
GO
EXEC sp_executesql N'
CREATE OR ALTER FUNCTION wf.wf_worker_is_omnibus(@capabilities json)
RETURNS BIT
AS
BEGIN
    IF @capabilities IS NULL
        RETURN 0;
    IF NOT EXISTS (SELECT 1 FROM OPENJSON(@capabilities))
        RETURN 0;
    IF EXISTS (
        SELECT 1
        FROM OPENJSON(@capabilities) WITH (value NVARCHAR(128) ''$'') AS caps
        WHERE caps.value = N''*''
    )
        RETURN 1;
    RETURN 0;
END;
'
GO
EXEC sp_executesql N'
CREATE OR ALTER FUNCTION wf.wf_worker_capability_allowed(
    @worker_capabilities json,
    @task_capability NVARCHAR(128)
)
RETURNS BIT
AS
BEGIN
    IF @task_capability IS NULL
        RETURN 1;
    IF wf.wf_worker_is_omnibus(@worker_capabilities) = 1
        RETURN 1;
    IF EXISTS (
        SELECT 1
        FROM OPENJSON(@worker_capabilities) WITH (value NVARCHAR(128) ''$'') AS caps
        WHERE caps.value = @task_capability
    )
        RETURN 1;
    RETURN 0;
END;
'
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_request_task]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.sp_worker_request_task
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @capability NVARCHAR(128) NULL,
    @max_lease_seconds INT = 300
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @lease_end DATETIME2(7) = DATEADD(SECOND, @max_lease_seconds, @now);
    DECLARE @worker_capabilities json;
    DECLARE @is_omnibus BIT;

    SELECT @worker_capabilities = w.capabilities
    FROM wf.worker AS w
    WHERE w.id = @worker_id;

    SET @is_omnibus = wf.wf_worker_is_omnibus(@worker_capabilities);

    IF @capability IS NOT NULL
       AND @is_omnibus = 0
       AND wf.wf_worker_capability_allowed(@worker_capabilities, @capability) = 0
    BEGIN
        RETURN;
    END

    BEGIN TRANSACTION;

    DECLARE @picked_ids TABLE (id BIGINT);

    ;WITH cte AS (
        SELECT TOP (1) ne.id
        FROM wf.node_execution AS ne WITH (ROWLOCK, READPAST, UPDLOCK)
        INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
        INNER JOIN wf.workflow_action AS wa ON wa.id = wn.workflow_action_id
        INNER JOIN wf.workflow_instance AS wi ON wi.id = ne.workflow_instance_id
        WHERE ne.status = N''READY''
          AND ne.input_json IS NOT NULL
          AND wn.node_type = N''ACTION''
          AND wi.status = N''RUNNING''
          AND (ne.available_at_utc IS NULL OR ne.available_at_utc <= @now)
          AND wf.wf_worker_capability_allowed(@worker_capabilities, wa.capability) = 1
          AND (
              @capability IS NULL
              OR wa.capability = @capability
              OR wa.capability IS NULL
          )
        ORDER BY ne.available_at_utc ASC, ne.id ASC
    )
    UPDATE ne
    SET status = N''RUNNING'',
        started_at_utc = @now
    OUTPUT inserted.id INTO @picked_ids(id)
    FROM wf.node_execution AS ne
    INNER JOIN cte ON cte.id = ne.id;

    DECLARE @picked BIGINT;
    SELECT @picked = id FROM @picked_ids;

    IF @picked IS NULL
    BEGIN
        ROLLBACK TRANSACTION;
        RETURN;
    END

    ;MERGE wf.task_lease AS t
    USING (SELECT @picked AS node_execution_id) AS s ON (t.node_execution_id = s.node_execution_id)
    WHEN MATCHED THEN
        UPDATE SET worker_id = @worker_id, lease_expires_at_utc = @lease_end, heartbeat_at_utc = @now
    WHEN NOT MATCHED THEN
        INSERT (node_execution_id, worker_id, lease_expires_at_utc, heartbeat_at_utc)
        VALUES (@picked, @worker_id, @lease_end, @now);

    COMMIT TRANSACTION;

    SELECT
        ne.id AS node_execution_id,
        ne.workflow_instance_id,
        wn.node_key,
        wa.action_name,
        wa.capability,
        ne.attempt_no,
        ne.input_json,
        ne.iteration_no
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    INNER JOIN wf.workflow_action AS wa ON wa.id = wn.workflow_action_id
    WHERE ne.id = @picked;
END;
'
GO

--
-- Create or alter procedure [wf].[sp_worker_heartbeat]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_heartbeat]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.sp_worker_heartbeat
    @node_execution_id BIGINT,
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @extend_seconds INT = 300
AS
BEGIN
    SET NOCOUNT ON;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    UPDATE tl
    SET lease_expires_at_utc = DATEADD(SECOND, @extend_seconds, @now),
        heartbeat_at_utc = @now
    FROM wf.task_lease AS tl
    WHERE tl.node_execution_id = @node_execution_id AND tl.worker_id = @worker_id;

    SELECT @@ROWCOUNT AS rows_updated;
END;
'
GO

--
-- Create or alter procedure [wf].[sp_worker_fail_task]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_fail_task]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.sp_worker_fail_task
    @node_execution_id BIGINT,
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @error_code INT,
    @error_message NVARCHAR(1024) NULL
AS
BEGIN
    SET NOCOUNT ON;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    IF NOT EXISTS (
        SELECT 1 FROM wf.task_lease WHERE node_execution_id = @node_execution_id AND worker_id = @worker_id
    )
        RETURN;

    UPDATE wf.node_execution
    SET status = N''FAILED'',
        engine_error_code = @error_code,
        engine_error_message = @error_message,
        ended_at_utc = SYSUTCDATETIME()
    WHERE id = @node_execution_id AND status = N''RUNNING'';

    DELETE FROM wf.task_lease WHERE node_execution_id = @node_execution_id;

    UPDATE wf.workflow_instance
    SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME()
    WHERE id = (SELECT workflow_instance_id FROM wf.node_execution WHERE id = @node_execution_id);
END;
'
GO

