--
-- Create or alter procedure [wf].[wf_repeat_continue]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_repeat_continue]')
GO
IF OBJECT_ID(N'wf.wf_repeat_continue', 'P') IS NULL
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_repeat_continue
    @repeat_execution_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @inst BIGINT;
    DECLARE @ctl BIGINT;
    DECLARE @ls BIGINT;
    DECLARE @cur INT;
    DECLARE @max INT;

    SELECT @inst = workflow_instance_id, @ctl = workflow_node_id FROM wf.node_execution WHERE id = @repeat_execution_id;
    SELECT TOP (1)
        @ls = id,
        @cur = current_iteration,
        @max = repeat_target_count
    FROM wf.loop_state
    WHERE scope_node_execution_id = @repeat_execution_id;

    IF @ls IS NULL
    BEGIN
        UPDATE wf.node_execution SET status = N''FAILED'', engine_error_code = 10007, ended_at_utc = SYSUTCDATETIME() WHERE id = @repeat_execution_id;
        UPDATE wf.workflow_instance SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME() WHERE id = @inst;
        RETURN;
    END

    SET @cur += 1;
    UPDATE wf.loop_state SET current_iteration = @cur WHERE id = @ls;

    IF @cur >= @max
    BEGIN
        UPDATE wf.node_execution SET status = N''SUCCEEDED'', ended_at_utc = SYSUTCDATETIME() WHERE id = @repeat_execution_id;
        EXEC wf.wf_engine_on_composite_complete @node_execution_id = @repeat_execution_id;
        RETURN;
    END

    DECLARE @body BIGINT;
    SELECT TOP (1) @body = child_node_id FROM wf.workflow_edge WHERE parent_node_id = @ctl AND branch_kind = N''BODY'' ORDER BY child_order ASC;

    DECLARE @cur1 INT = @cur + 1;
    EXEC wf.wf_engine_activate
        @workflow_instance_id = @inst,
        @workflow_node_id = @body,
        @parent_node_execution_id = @repeat_execution_id,
        @iteration_no = @cur1,
        @sequence_index = NULL,
        @parallel_index = NULL;
END;
'
GO

--
-- Create or alter procedure [wf].[wf_engine_on_action_complete]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_engine_on_action_complete]')
GO
IF OBJECT_ID(N'wf.sp_worker_submit_result', N'P') IS NOT NULL
    DROP PROCEDURE wf.sp_worker_submit_result;
IF OBJECT_ID(N'wf.wf_engine_on_action_complete', N'P') IS NOT NULL
    DROP PROCEDURE wf.wf_engine_on_action_complete;
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_engine_on_action_complete
    @action_execution_id BIGINT,
    @result_code INT,
    @output_json json NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @inst BIGINT;
    DECLARE @wn BIGINT;
    DECLARE @parent BIGINT;

    SELECT @inst = workflow_instance_id, @wn = workflow_node_id, @parent = parent_node_execution_id
    FROM wf.node_execution WHERE id = @action_execution_id;

    IF @result_code < 0
    BEGIN
        UPDATE wf.node_execution
        SET status = N''FAILED'',
            result_code = @result_code,
            output_json = @output_json,
            ended_at_utc = SYSUTCDATETIME(),
            engine_error_code = @result_code
        WHERE id = @action_execution_id;

        DELETE FROM wf.task_lease WHERE node_execution_id = @action_execution_id;

        UPDATE wf.workflow_instance
        SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME()
        WHERE id = @inst;

        RETURN;
    END

    UPDATE wf.node_execution
    SET status = N''SUCCEEDED'',
        result_code = @result_code,
        output_json = @output_json,
        ended_at_utc = SYSUTCDATETIME()
    WHERE id = @action_execution_id;

    DELETE FROM wf.task_lease WHERE node_execution_id = @action_execution_id;

    IF @parent IS NULL
    BEGIN
        UPDATE wf.workflow_instance SET status = N''COMPLETED'', completed_at_utc = SYSUTCDATETIME() WHERE id = @inst;
        RETURN;
    END

    DECLARE @ptype VARCHAR(32);
    SELECT @ptype = wn.node_type
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    WHERE ne.id = @parent;

    IF @ptype = N''SEQUENCE''
        EXEC wf.wf_sequence_continue @sequence_execution_id = @parent;

    ELSE IF @ptype = N''PARALLEL''
        EXEC wf.wf_parallel_continue @parallel_execution_id = @parent;

    ELSE IF @ptype IN (N''IF'', N''SWITCH'')
    BEGIN
        UPDATE wf.node_execution SET status = N''SUCCEEDED'', ended_at_utc = SYSUTCDATETIME() WHERE id = @parent;
        EXEC wf.wf_engine_on_composite_complete @node_execution_id = @parent;
    END

    ELSE IF @ptype = N''REPEAT''
        EXEC wf.wf_repeat_continue @repeat_execution_id = @parent;

    ELSE IF @ptype = N''WHILE''
        EXEC wf.wf_while_continue @while_execution_id = @parent;

    /* FOREACH arrives with wf_sql_foreach_support.sql; dispatch through the router so
       re-running this base script never drops FOREACH continuation. */
    ELSE IF @ptype = N''FOREACH''
        EXEC wf.wf_foreach_route_continue @foreach_execution_id = @parent;
END;
'
GO

--
-- Create or alter procedure [wf].[sp_worker_submit_result]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_worker_submit_result]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.sp_worker_submit_result
    @node_execution_id BIGINT,
    @worker_id BIGINT,
    @worker_token NVARCHAR(4000),
    @result_code INT,
    @output_json json NULL,
    @accepted BIT OUTPUT,
    @instance_status VARCHAR(32) OUTPUT,
    @next_ready_count INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @accepted = 0;
    SET @next_ready_count = 0;
    SET @instance_status = NULL;

    EXEC wf.wf_worker_authenticate @worker_id = @worker_id, @worker_token = @worker_token;

    BEGIN TRANSACTION;

    DECLARE @lease_worker BIGINT;
    SELECT @lease_worker = worker_id FROM wf.task_lease WITH (UPDLOCK, HOLDLOCK) WHERE node_execution_id = @node_execution_id;

    IF @lease_worker IS NULL OR @lease_worker <> @worker_id
    BEGIN
        ROLLBACK TRANSACTION;
        RETURN;
    END

    DECLARE @cur_status VARCHAR(32);
    SELECT @cur_status = status FROM wf.node_execution WITH (UPDLOCK, HOLDLOCK) WHERE id = @node_execution_id;

    IF @cur_status <> N''RUNNING''
    BEGIN
        ROLLBACK TRANSACTION;
        RETURN;
    END

    DECLARE @output_json_text NVARCHAR(MAX) = CASE
        WHEN @output_json IS NULL THEN NULL
        ELSE CONVERT(NVARCHAR(MAX), @output_json)
    END;

    EXEC wf.wf_engine_on_action_complete
        @action_execution_id = @node_execution_id,
        @result_code = @result_code,
        @output_json = @output_json_text;

    SET @accepted = 1;

    SELECT @instance_status = status FROM wf.workflow_instance WHERE id = (SELECT workflow_instance_id FROM wf.node_execution WHERE id = @node_execution_id);

    SELECT @next_ready_count = COUNT(*)
    FROM wf.node_execution
    WHERE workflow_instance_id = (SELECT workflow_instance_id FROM wf.node_execution WHERE id = @node_execution_id)
      AND status = N''READY'';

    COMMIT TRANSACTION;
END;
'
GO

