--
-- Create or alter procedure [wf].[wf_seed_execution_context]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_seed_execution_context]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_seed_execution_context
    @node_execution_id BIGINT,
    @workflow_instance_id BIGINT,
    @workflow_node_id BIGINT,
    @parent_node_execution_id BIGINT NULL,
    @iteration_no INT,
    @sequence_index INT NULL,
    @parallel_index INT NULL
AS
BEGIN
    SET NOCOUNT ON;

    DELETE FROM wf.execution_context WHERE node_execution_id = @node_execution_id;

    INSERT INTO wf.execution_context (node_execution_id, context_key, context_value_json)
    VALUES (@node_execution_id, N''ctx.iterationNo'', CAST(@iteration_no AS NVARCHAR(32)));

    IF @sequence_index IS NOT NULL
        INSERT INTO wf.execution_context (node_execution_id, context_key, context_value_json)
        VALUES (@node_execution_id, N''ctx.sequenceIndex'', CAST(@sequence_index AS NVARCHAR(32)));

    IF @parallel_index IS NOT NULL
        INSERT INTO wf.execution_context (node_execution_id, context_key, context_value_json)
        VALUES (@node_execution_id, N''ctx.parallelIndex'', CAST(@parallel_index AS NVARCHAR(32)));

    IF @parent_node_execution_id IS NOT NULL
    BEGIN
        DECLARE @prc INT;
        SELECT @prc = result_code FROM wf.node_execution WHERE id = @parent_node_execution_id;
        INSERT INTO wf.execution_context (node_execution_id, context_key, context_value_json)
        VALUES (@node_execution_id, N''ctx.parent.resultCode'', CAST(@prc AS NVARCHAR(32)));
    END
END;
'
GO

--
-- Create or alter function [wf].[wf_json_fragment_from_string]
--
GO
PRINT (N'Create or alter function [wf].[wf_json_fragment_from_string]')
GO
IF NOT EXISTS (SELECT 1 FROM sys.objects WITH (NOLOCK) WHERE object_id = OBJECT_ID(N'wf.wf_json_fragment_from_string') AND type IN ('IF', 'FN', 'TF'))
EXEC sp_executesql N'
CREATE OR ALTER FUNCTION wf.wf_json_fragment_from_string(@s NVARCHAR(MAX))
RETURNS NVARCHAR(MAX)
AS
BEGIN
    RETURN N''"'' + REPLACE(REPLACE(REPLACE(@s, N''\'', N''\\''), N''"'', N''\"''), CHAR(10), N''\n'') + N''"'';
END;
'
GO

--
-- Create or alter function [wf].[wf_try_task_output_json]
--
GO
PRINT (N'Create or alter function [wf].[wf_try_task_output_json]')
GO
EXEC sp_executesql N'
CREATE OR ALTER FUNCTION wf.wf_try_task_output_json(@workflow_instance_id BIGINT, @node_key NVARCHAR(128), @jsonPath NVARCHAR(4000))
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @out NVARCHAR(MAX);
    SELECT TOP (1) @out = CAST(ne.output_json AS NVARCHAR(MAX))
    FROM wf.node_execution AS ne
    INNER JOIN wf.workflow_node AS wn ON wn.id = ne.workflow_node_id
    WHERE ne.workflow_instance_id = @workflow_instance_id
      AND wn.node_key = @node_key
      AND ne.status = N''SUCCEEDED''
    ORDER BY ne.ended_at_utc DESC, ne.id DESC;

    IF @out IS NULL RETURN NULL;

    IF @jsonPath IS NULL OR LTRIM(RTRIM(@jsonPath)) = N'''' RETURN @out;

    IF LEFT(@jsonPath, 1) <> N''$'' SET @jsonPath = N''$.'' + @jsonPath;

    DECLARE @jq NVARCHAR(MAX) = JSON_QUERY(@out, @jsonPath);
    IF @jq IS NOT NULL RETURN @jq;

    DECLARE @jv NVARCHAR(MAX) = JSON_VALUE(@out, @jsonPath);
    IF @jv IS NULL RETURN NULL;

    DECLARE @bi BIGINT = TRY_CONVERT(BIGINT, @jv);
    IF @bi IS NOT NULL AND CAST(@bi AS NVARCHAR(50)) = LTRIM(RTRIM(@jv))
        RETURN CAST(@bi AS NVARCHAR(50));

    RETURN wf.wf_json_fragment_from_string(@jv);
END;
'
GO

--
-- Create or alter procedure [wf].[wf_resolve_token]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_resolve_token]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_resolve_token
    @token NVARCHAR(1024),
    @node_execution_id BIGINT,
    @workflow_instance_id BIGINT,
    @out_fragment NVARCHAR(MAX) OUTPUT,
    @failed BIT OUTPUT,
    @fail_code INT OUTPUT,
    @fail_msg NVARCHAR(1024) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @failed = 0;
    SET @fail_code = NULL;
    SET @fail_msg = NULL;

    IF CHARINDEX(N'' '', @token) > 0 OR CHARINDEX(N''+'', @token) > 0 OR CHARINDEX(N''('', @token) > 0
    BEGIN
        SET @failed = 1;
        SET @fail_code = 10002;
        SET @fail_msg = N''Unsupported placeholder expression.'';
        RETURN;
    END

    IF LEFT(@token, 9) = N''ctx.task.''
    BEGIN
        DECLARE @rest NVARCHAR(1024) = SUBSTRING(@token, 10, 4000);
        DECLARE @dot INT = CHARINDEX(N''.'', @rest);
        DECLARE @nk NVARCHAR(128);
        DECLARE @tail NVARCHAR(1024);

        IF @dot = 0
        BEGIN
            SET @failed = 1;
            SET @fail_code = 10002;
            SET @fail_msg = N''Invalid ctx.task reference.'';
            RETURN;
        END

        SET @nk = LEFT(@rest, @dot - 1);
        SET @tail = SUBSTRING(@rest, @dot + 1, 4000);

        IF @tail = N''resultCode''
        BEGIN
            DECLARE @rc INT = wf.wf_try_task_result_code(@workflow_instance_id, @nk);
            SET @out_fragment = CAST(@rc AS NVARCHAR(32));
            RETURN;
        END

        IF LEFT(@tail, 7) = N''output.''
        BEGIN
            DECLARE @jp NVARCHAR(4000) = SUBSTRING(@tail, 8, 4000);
            DECLARE @jq NVARCHAR(MAX) = wf.wf_try_task_output_json(@workflow_instance_id, @nk, @jp);
            SET @out_fragment = @jq;
            RETURN;
        END

        SET @failed = 1;
        SET @fail_code = 10002;
        SET @fail_msg = N''Unsupported ctx.task tail.'';
        RETURN;
    END

    IF LEFT(@token, 4) = N''ctx.''
    BEGIN
        DECLARE @v NVARCHAR(MAX);
        SELECT @v = wf.wf_json_unbox(CAST(context_value_json AS NVARCHAR(MAX)))
        FROM wf.execution_context
        WHERE node_execution_id = @node_execution_id AND context_key = @token;

        IF @v IS NULL
        BEGIN
            SET @failed = 1;
            SET @fail_code = 10001;
            SET @fail_msg = N''Missing context value for '' + @token;
            RETURN;
        END

        SET @out_fragment = @v;
        RETURN;
    END

    SET @failed = 1;
    SET @fail_code = 10002;
    SET @fail_msg = N''Unsupported token.'';
END;
'
GO

--
-- Create or alter procedure [wf].[wf_resolve_placeholders]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_resolve_placeholders]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_resolve_placeholders
    @text NVARCHAR(MAX),
    @node_execution_id BIGINT,
    @workflow_instance_id BIGINT,
    @resolved NVARCHAR(MAX) OUTPUT,
    @failed BIT OUTPUT,
    @fail_code INT OUTPUT,
    @fail_msg NVARCHAR(1024) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @resolved = @text;
    SET @failed = 0;

    DECLARE @start INT;
    DECLARE @end INT;
    DECLARE @token NVARCHAR(1024);
    DECLARE @frag NVARCHAR(MAX);
    DECLARE @tf BIT;
    DECLARE @fc INT;
    DECLARE @fm NVARCHAR(1024);

    WHILE CHARINDEX(N''${'', @resolved) > 0
    BEGIN
        SET @start = CHARINDEX(N''${'', @resolved);
        SET @end = CHARINDEX(N''}'', @resolved, @start + 2);
        IF @end = 0 BREAK;

        SET @token = SUBSTRING(@resolved, @start + 2, @end - (@start + 2));

        EXEC wf.wf_resolve_token
            @token = @token,
            @node_execution_id = @node_execution_id,
            @workflow_instance_id = @workflow_instance_id,
            @out_fragment = @frag OUTPUT,
            @failed = @tf OUTPUT,
            @fail_code = @fc OUTPUT,
            @fail_msg = @fm OUTPUT;

        IF @tf = 1
        BEGIN
            SET @failed = 1;
            SET @fail_code = @fc;
            SET @fail_msg = @fm;
            RETURN;
        END

        SET @resolved = STUFF(@resolved, @start, @end - @start + 1, ISNULL(@frag, N''null''));
    END
END;
'
GO

--
-- Create or alter procedure [wf].[wf_build_input_json_for_action]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_build_input_json_for_action]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_build_input_json_for_action
    @node_execution_id BIGINT,
    @workflow_instance_id BIGINT,
    @workflow_node_id BIGINT,
    @final_json NVARCHAR(MAX) OUTPUT,
    @failed BIT OUTPUT,
    @fail_code INT OUTPUT,
    @fail_msg NVARCHAR(1024) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @failed = 0;

    DECLARE @template NVARCHAR(MAX) = N''{}'';
    IF EXISTS (SELECT 1 FROM wf.workflow_input_template WHERE workflow_node_id = @workflow_node_id)
        SELECT @template = CAST(template_json AS NVARCHAR(MAX)) FROM wf.workflow_input_template WHERE workflow_node_id = @workflow_node_id;

    DECLARE @cur NVARCHAR(MAX);
    DECLARE @tf BIT;
    DECLARE @fc INT;
    DECLARE @fm NVARCHAR(1024);

    EXEC wf.wf_resolve_placeholders
        @text = @template,
        @node_execution_id = @node_execution_id,
        @workflow_instance_id = @workflow_instance_id,
        @resolved = @cur OUTPUT,
        @failed = @tf OUTPUT,
        @fail_code = @fc OUTPUT,
        @fail_msg = @fm OUTPUT;

    IF @tf = 1
    BEGIN
        SET @failed = 1;
        SET @fail_code = @fc;
        SET @fail_msg = @fm;
        RETURN;
    END

    IF ISJSON(@cur) = 0
    BEGIN
        SET @failed = 1;
        SET @fail_code = 10008;
        SET @fail_msg = N''Template JSON is invalid after placeholder resolution.'';
        RETURN;
    END

    DECLARE @bid BIGINT;
    DECLARE @path NVARCHAR(1024);
    DECLARE @expr NVARCHAR(1024);
    DECLARE @req BIT;

    DECLARE c CURSOR LOCAL FAST_FORWARD FOR
        SELECT id, target_json_path, source_expr, is_required
        FROM wf.workflow_input_binding
        WHERE workflow_node_id = @workflow_node_id
        ORDER BY id;

    OPEN c;
    FETCH NEXT FROM c INTO @bid, @path, @expr, @req;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        DECLARE @frag NVARCHAR(MAX);

        EXEC wf.wf_resolve_placeholders
            @text = @expr,
            @node_execution_id = @node_execution_id,
            @workflow_instance_id = @workflow_instance_id,
            @resolved = @frag OUTPUT,
            @failed = @tf OUTPUT,
            @fail_code = @fc OUTPUT,
            @fail_msg = @fm OUTPUT;

        IF @tf = 1 AND @req = 1
        BEGIN
            SET @failed = 1;
            SET @fail_code = @fc;
            SET @fail_msg = @fm;
            CLOSE c;
            DEALLOCATE c;
            RETURN;
        END

        IF @tf = 1 AND (@req = 0 OR @req IS NULL)
            SET @frag = N''null'';

        IF LEFT(@path, 1) <> N''$'' SET @path = N''$.'' + @path;

        IF ISNULL(@frag, N'''') = N'''' SET @frag = N''null'';

        IF ISJSON(@frag) = 1
            SET @cur = JSON_MODIFY(@cur, @path, JSON_QUERY(@frag));
        ELSE
            SET @cur = JSON_MODIFY(@cur, @path, JSON_QUERY(wf.wf_json_fragment_from_string(@frag)));

        FETCH NEXT FROM c INTO @bid, @path, @expr, @req;
    END

    CLOSE c;
    DEALLOCATE c;

    SET @final_json = @cur;
END;
'
GO

--
-- Create or alter procedure [wf].[wf_engine_activate]
--
GO
PRINT (N'Create or alter procedure [wf].[wf_engine_activate]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.wf_engine_activate
    @workflow_instance_id BIGINT,
    @workflow_node_id BIGINT,
    @parent_node_execution_id BIGINT NULL,
    @iteration_no INT = 0,
    @sequence_index INT NULL,
    @parallel_index INT NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @node_type VARCHAR(32);
    DECLARE @version_id BIGINT;
    DECLARE @node_key NVARCHAR(128);

    SELECT @node_type = node_type, @version_id = workflow_version_id, @node_key = node_key
    FROM wf.workflow_node
    WHERE id = @workflow_node_id;

    IF @node_type IS NULL RETURN;

    IF @node_type = N''ACTION''
    BEGIN
        DECLARE @ne_id BIGINT;
        INSERT INTO wf.node_execution (
            workflow_instance_id, workflow_node_id, status, attempt_no,
            parent_node_execution_id, iteration_no, available_at_utc
        )
        VALUES (
            @workflow_instance_id, @workflow_node_id, N''PENDING'', 1,
            @parent_node_execution_id, @iteration_no, NULL
        );
        SET @ne_id = SCOPE_IDENTITY();

        EXEC wf.wf_seed_execution_context
            @node_execution_id = @ne_id,
            @workflow_instance_id = @workflow_instance_id,
            @workflow_node_id = @workflow_node_id,
            @parent_node_execution_id = @parent_node_execution_id,
            @iteration_no = @iteration_no,
            @sequence_index = @sequence_index,
            @parallel_index = @parallel_index;

        DECLARE @fj NVARCHAR(MAX);
        DECLARE @failed BIT;
        DECLARE @fc INT;
        DECLARE @fm NVARCHAR(1024);

        EXEC wf.wf_build_input_json_for_action
            @node_execution_id = @ne_id,
            @workflow_instance_id = @workflow_instance_id,
            @workflow_node_id = @workflow_node_id,
            @final_json = @fj OUTPUT,
            @failed = @failed OUTPUT,
            @fail_code = @fc OUTPUT,
            @fail_msg = @fm OUTPUT;

        IF @failed = 1
        BEGIN
            UPDATE wf.node_execution
            SET status = N''FAILED'',
                engine_error_code = @fc,
                engine_error_message = @fm,
                ended_at_utc = SYSUTCDATETIME()
            WHERE id = @ne_id;

            UPDATE wf.workflow_instance
            SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME()
            WHERE id = @workflow_instance_id;

            RETURN;
        END

        UPDATE wf.node_execution
        SET status = N''READY'',
            input_json = CAST(@fj AS json),
            available_at_utc = SYSUTCDATETIME()
        WHERE id = @ne_id;
        RETURN;
    END

    /* Composite: create RUNNING execution row */
    DECLARE @pex BIGINT;
    INSERT INTO wf.node_execution (
        workflow_instance_id, workflow_node_id, status, attempt_no,
        parent_node_execution_id, iteration_no, started_at_utc, available_at_utc
    )
    VALUES (
        @workflow_instance_id, @workflow_node_id, N''RUNNING'', 1,
        @parent_node_execution_id, @iteration_no, SYSUTCDATETIME(), SYSUTCDATETIME()
    );
    SET @pex = SCOPE_IDENTITY();

    IF @node_type = N''SEQUENCE''
    BEGIN
        DECLARE @child1 BIGINT;
        SELECT TOP (1) @child1 = child_node_id
        FROM wf.workflow_edge
        WHERE parent_node_id = @workflow_node_id
        ORDER BY child_order ASC;

        IF @child1 IS NULL
        BEGIN
            UPDATE wf.node_execution SET status = N''SUCCEEDED'', ended_at_utc = SYSUTCDATETIME() WHERE id = @pex;
            EXEC wf.wf_engine_on_composite_complete @node_execution_id = @pex;
            RETURN;
        END

        DECLARE @ord INT = 0;
        SELECT TOP (1) @ord = child_order FROM wf.workflow_edge WHERE parent_node_id = @workflow_node_id ORDER BY child_order ASC;

        EXEC wf.wf_engine_activate
            @workflow_instance_id = @workflow_instance_id,
            @workflow_node_id = @child1,
            @parent_node_execution_id = @pex,
            @iteration_no = @iteration_no,
            @sequence_index = @ord,
            @parallel_index = NULL;
        RETURN;
    END

    IF @node_type = N''PARALLEL''
    BEGIN
        DECLARE @cid BIGINT;
        DECLARE @pidx INT = 0;
        DECLARE pc CURSOR LOCAL FAST_FORWARD FOR
            SELECT child_node_id
            FROM wf.workflow_edge
            WHERE parent_node_id = @workflow_node_id
            ORDER BY child_order ASC;

        OPEN pc;
        FETCH NEXT FROM pc INTO @cid;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC wf.wf_engine_activate
                @workflow_instance_id = @workflow_instance_id,
                @workflow_node_id = @cid,
                @parent_node_execution_id = @pex,
                @iteration_no = @iteration_no,
                @sequence_index = NULL,
                @parallel_index = @pidx;

            SET @pidx += 1;
            FETCH NEXT FROM pc INTO @cid;
        END

        CLOSE pc;
        DEALLOCATE pc;
        RETURN;
    END

    IF @node_type = N''IF''
    BEGIN
        DECLARE @cref NVARCHAR(128);
        SELECT @cref = condition_ref_node_key FROM wf.workflow_node WHERE id = @workflow_node_id;

        DECLARE @cond INT = wf.wf_try_task_result_code(@workflow_instance_id, @cref);
        DECLARE @pick VARCHAR(32) = CASE WHEN @cond IS NOT NULL AND @cond <> 0 THEN N''THEN'' ELSE N''ELSE'' END;

        DECLARE @ifchild BIGINT;
        SELECT TOP (1) @ifchild = child_node_id
        FROM wf.workflow_edge
        WHERE parent_node_id = @workflow_node_id AND branch_kind = @pick
        ORDER BY child_order ASC;

        IF @ifchild IS NULL
        BEGIN
            UPDATE wf.node_execution SET status = N''FAILED'', engine_error_code = 10003, engine_error_message = N''Missing IF branch.'', ended_at_utc = SYSUTCDATETIME() WHERE id = @pex;
            UPDATE wf.workflow_instance SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME() WHERE id = @workflow_instance_id;
            RETURN;
        END

        EXEC wf.wf_engine_activate
            @workflow_instance_id = @workflow_instance_id,
            @workflow_node_id = @ifchild,
            @parent_node_execution_id = @pex,
            @iteration_no = @iteration_no,
            @sequence_index = NULL,
            @parallel_index = NULL;
        RETURN;
    END

    IF @node_type = N''SWITCH''
    BEGIN
        DECLARE @sref NVARCHAR(128);
        SELECT @sref = switch_ref_node_key FROM wf.workflow_node WHERE id = @workflow_node_id;

        DECLARE @sv INT = wf.wf_try_task_result_code(@workflow_instance_id, @sref);

        DECLARE @swchild BIGINT;
        SELECT TOP (1) @swchild = child_node_id
        FROM wf.workflow_edge
        WHERE parent_node_id = @workflow_node_id AND branch_kind = N''CASE'' AND switch_case_value = @sv
        ORDER BY child_order ASC;

        IF @swchild IS NULL
            SELECT TOP (1) @swchild = child_node_id
            FROM wf.workflow_edge
            WHERE parent_node_id = @workflow_node_id AND branch_kind = N''DEFAULT''
            ORDER BY child_order ASC;

        IF @swchild IS NULL
        BEGIN
            UPDATE wf.node_execution SET status = N''FAILED'', engine_error_code = 10004, engine_error_message = N''Missing SWITCH case.'', ended_at_utc = SYSUTCDATETIME() WHERE id = @pex;
            UPDATE wf.workflow_instance SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME() WHERE id = @workflow_instance_id;
            RETURN;
        END

        EXEC wf.wf_engine_activate
            @workflow_instance_id = @workflow_instance_id,
            @workflow_node_id = @swchild,
            @parent_node_execution_id = @pex,
            @iteration_no = @iteration_no,
            @sequence_index = NULL,
            @parallel_index = NULL;
        RETURN;
    END

    IF @node_type = N''REPEAT''
    BEGIN
        DECLARE @rcount INT;
        SELECT @rcount = repeat_count FROM wf.workflow_node WHERE id = @workflow_node_id;

        IF @rcount IS NULL OR @rcount < 1 SET @rcount = 1;

        INSERT INTO wf.loop_state (workflow_instance_id, control_node_id, scope_node_execution_id, current_iteration, repeat_target_count)
        VALUES (@workflow_instance_id, @workflow_node_id, @pex, 0, @rcount);

        DECLARE @body BIGINT;
        SELECT TOP (1) @body = child_node_id FROM wf.workflow_edge WHERE parent_node_id = @workflow_node_id AND branch_kind = N''BODY'' ORDER BY child_order ASC;

        IF @body IS NULL
        BEGIN
            UPDATE wf.node_execution SET status = N''FAILED'', engine_error_code = 10005, ended_at_utc = SYSUTCDATETIME() WHERE id = @pex;
            UPDATE wf.workflow_instance SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME() WHERE id = @workflow_instance_id;
            RETURN;
        END

        EXEC wf.wf_engine_activate
            @workflow_instance_id = @workflow_instance_id,
            @workflow_node_id = @body,
            @parent_node_execution_id = @pex,
            @iteration_no = 1,
            @sequence_index = NULL,
            @parallel_index = NULL;
        RETURN;
    END

    IF @node_type = N''WHILE''
    BEGIN
        DECLARE @wbody BIGINT;
        SELECT TOP (1) @wbody = child_node_id FROM wf.workflow_edge WHERE parent_node_id = @workflow_node_id AND branch_kind = N''BODY'' ORDER BY child_order ASC;

        IF @wbody IS NULL
        BEGIN
            UPDATE wf.node_execution SET status = N''FAILED'', engine_error_code = 10006, ended_at_utc = SYSUTCDATETIME() WHERE id = @pex;
            UPDATE wf.workflow_instance SET status = N''FAILED'', completed_at_utc = SYSUTCDATETIME() WHERE id = @workflow_instance_id;
            RETURN;
        END

        DECLARE @wcref NVARCHAR(128);
        SELECT @wcref = condition_ref_node_key FROM wf.workflow_node WHERE id = @workflow_node_id;

        DECLARE @wcond INT = wf.wf_try_task_result_code(@workflow_instance_id, @wcref);

        IF @wcond IS NULL OR @wcond = 0
        BEGIN
            UPDATE wf.node_execution SET status = N''SUCCEEDED'', ended_at_utc = SYSUTCDATETIME() WHERE id = @pex;
            EXEC wf.wf_engine_on_composite_complete @node_execution_id = @pex;
            RETURN;
        END

        EXEC wf.wf_engine_activate
            @workflow_instance_id = @workflow_instance_id,
            @workflow_node_id = @wbody,
            @parent_node_execution_id = @pex,
            @iteration_no = 1,
            @sequence_index = NULL,
            @parallel_index = NULL;
        RETURN;
    END
END;
'
GO

--
-- Create or alter procedure [wf].[sp_start_workflow_instance]
--
GO
PRINT (N'Create or alter procedure [wf].[sp_start_workflow_instance]')
GO
EXEC sp_executesql N'
CREATE OR ALTER PROCEDURE wf.sp_start_workflow_instance
    @workflow_instance_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @vid BIGINT;
    DECLARE @root BIGINT;

    SELECT @vid = workflow_version_id FROM wf.workflow_instance WHERE id = @workflow_instance_id;
    SELECT @root = root_node_id FROM wf.workflow_version WHERE id = @vid;

    IF @root IS NULL
        THROW 50001, N''Workflow version has no root_node_id.'', 1;

    UPDATE wf.workflow_instance
    SET 
      status = N''RUNNING'', 
      started_at_utc = SYSUTCDATETIME()
    WHERE id = @workflow_instance_id;

    EXEC wf.wf_engine_activate
        @workflow_instance_id = @workflow_instance_id,
        @workflow_node_id = @root,
        @parent_node_execution_id = NULL,
        @iteration_no = 0,
        @sequence_index = NULL,
        @parallel_index = NULL;
END;
'
GO